package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsAny(CharSequence cs, char[] searchChars)
 */
public class StringUtils_containsAny_TriageGen1Test {

    @Test
    public void testContainsAny_NullCs() {
        assertFalse(StringUtils.containsAny(null, new char[]{'a'}));
    }

    @Test
    public void testContainsAny_EmptyCs() {
        assertFalse(StringUtils.containsAny("", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse(StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_MatchFirstChar() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_MatchLastChar() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse(StringUtils.containsAny("abc", new char[]{'d', 'e'}));
    }

    @Test
    public void testContainsAny_BMP_Match() {
        // Basic Multilingual Plane character
        assertTrue(StringUtils.containsAny("hello", new char[]{'e'}));
    }

    @Test
    public void testContainsAny_Supplementary_Match() {
        // Testing supplementary characters (Surrogate pairs)
        // U+1F600 (Grinning Face) is represented by \uD83D\uDE00
        String emoji = "\uD83D\uDE00"; 
        char[] searchChars = new char[]{\uD83D, \uDE00};

        assertTrue("Should match supplementary character pair", 
            StringUtils.containsAny(emoji, searchChars));
    }

    @Test
    public void testContainsAny_Supplementary_PartialMatch_Fail() {
        // High surrogate matches, but the next char in searchChars is different
        // or the next char in cs is different.
        String emoji = "\uD83D\uDE00"; // Grinning Face
        char[] wrongPair = new char[]{\uD83D, \uDE01}; // Different low surrogate

        // The code logic: if searchChars[j] == ch (the high surrogate)
        // and it's not the last index, it checks searchChars[j+1] == cs.charAt(i+1)
        assertFalse(StringUtils.containsAny(emoji, wrongPair));
    }

    @Test
    public void testContainsAny_Supplementary_EdgeCase_EndOfString() {
        // High surrogate is the last character of the string (invalid string, but tests branch)
        String broken = "\uD83D";
        char[] searchChars = new char[]{\uD83D, \uDE00};

        // i is csLastIndex, so it should fall into the 'else' block for BMP logic
        // because (i < csLastIndex) is false.
        assertTrue(StringUtils.containsAny(broken, searchChars));
    }

    @Test
    public void testContainsAny_Supplementary_EdgeCase_SearchCharsEnd() {
        // High surrogate matches, but it is the last char in searchChars array
        String emoji = "\uD83D\uDE00";
        char[] searchChars = new char[]{\uD83D};

        // j is searchLastIndex, so it should fall into the 'else' block
        assertTrue(StringUtils.containsAny(emoji, searchChars));
    }

    @Test
    public void testContainsAny_Supplementary_HighSurrogateLimit() {
        // ch <= Character.MAX_HIGH_SURROGATE
        // Max high surrogate is \uDBFF
        String high = "\uDBFF";
        char[] search = new char[]{\uDBFF};
        assertTrue(StringUtils.containsAny(high, search));
    }
}
